import React, {
  useCallback,
  useRef,
  useState,
} from 'react';
import {
  useDispatch,
  useSelector,
} from 'react-redux';
import { useTranslation } from 'react-i18next';

import {
  addMessage,
  clear as clearLog,
  selectLog,
  selectLogTimestamped,
} from './logSlice';
import { selectIsFlashing } from '../../Containers/App/stateSlice';

import './style.scss';

function Log() {
  const { t } = useTranslation('common');
  const dispatch = useDispatch();
  const messages = useSelector(selectLogTimestamped);
  const log = useSelector(selectLog);
  const isFlashing = useSelector(selectIsFlashing);
  const [ expanded, setExpanded] = useState(false);
  const wrapperRef = useRef(null);

  const messageElements = messages.slice(0).reverse()
    .map((message, index) => (
      <div key={index}>
        <span className="date">
          {message.date}

          &nbsp;@&nbsp;
        </span>

        <span className="time">
          {message.time}

          &nbsp;--&nbsp;
        </span>

        {message.html}
      </div>
    ));

  const toggleExpanded = useCallback(() => {
    setExpanded(!expanded);
  }, [expanded]);

  const handleSaveLog = useCallback(() => {
    const element = document.createElement("a");
    const file = new Blob([log.join("\n")], { type: 'text/plain' });
    element.href = URL.createObjectURL(file);
    element.download = "esc-configurator-log.txt";
    document.body.appendChild(element);
    element.click();

    // The log is kept after saving it: a later save still holds everything
    // (essais M6 and Q6: saved files missed the start of the session)
  }, [log]);

  const handleCopyLog = useCallback(async() => {
    try {
      await navigator.clipboard.writeText(log.join("\n"));
      dispatch(addMessage({
        message: 'logCopied',
        params: {},
      }));
    } catch(e) {
      console.debug('Could not copy the log', e);
      dispatch(addMessage({
        message: 'logCopyFailed',
        params: {},
      }));
    }
  }, [dispatch, log]);

  // Ctrl+A in the log selects the log only, not the whole page
  const handleKeyDown = useCallback((e) => {
    const isSelectAll = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'a';
    if(!isSelectAll) {
      return;
    }

    e.preventDefault();
    const range = document.createRange();
    range.selectNodeContents(wrapperRef.current);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }, []);

  const handleClearLog = useCallback(() => {
    dispatch(clearLog());
  }, [dispatch]);

  // The links have their own line above the log: never over the text nor
  // the scrollbar (TrueGlide, 08/11)
  return (
    <div className="log-panel">
      <div className="logswitch">
        <button
          onClick={handleSaveLog}
          type="button"
        >
          {t('escButtonSaveLog')}
        </button>

        <button
          onClick={handleCopyLog}
          type="button"
        >
          {t('escButtonCopyLog')}
        </button>

        <button
          disabled={isFlashing}
          onClick={handleClearLog}
          title={isFlashing ? t('escButtonClearLogFlashing') : undefined}
          type="button"
        >
          {t('escButtonClearLog')}
        </button>

        <button
          id="showlog"
          onClick={toggleExpanded}
          type="button"
        >
          {expanded ? t('hideLog') : t('showLog')}
        </button>
      </div>

      <div
        className={expanded ? 'expanded' : ''}
        id="log"
      >
        <div
          className="wrapper"
          onKeyDown={handleKeyDown}
          ref={wrapperRef}
          role="log"
          tabIndex={0}
        >
          {messageElements}
        </div>
      </div>
    </div>
  );
}

export default React.memo(Log);
